    parser=argparse.ArgumentParser();parser.add_argument('--out',type=Path,default=ROOT/'evaluation/data');args=parser.parse_args();rows=[]
    def add(domain,level,messages,specs,links=(),missing=(),questions=(),tags=(),phenomena=(),rationale='',parent=None):
        case_id=f'N{len(rows)+1:02d}';family=parent.family_id if parent else 'novel:'+domain+':'+level
        ms=[{'id':'m'+str(i+1),'speaker_id':speaker,'text':text} for i,(speaker,text) in enumerate(messages)]
        spans=[];events=[];arguments=[];people={}
        for i,spec in enumerate(specs):
            mi,quote,action,obj,*options=spec;opt=options[0] if options else {};message=ms[mi]
            speaker=message['speaker_id'];sid='s'+str(i);eid='e'+str(i);at=message['text'].index(quote)
            spans.append({'id':sid,'message_id':message['id'],'start':at,'end':at+len(quote),'quote':quote,'label':'action'})
            attributes=dict(zip(ATTRS,[action,obj,opt.get('speech','request'),opt.get('polarity','positive'),opt.get('temporal','requested'),opt.get('modality','request')]))
            scope=opt.get('scope','case:main')
            events.append({'id':eid,'anchor_id':sid,'attributes':attributes,'transaction_id':scope,'description':quote,'information_status':opt.get('information_status','claimed'),'argument_refs':[]})
            if speaker:
                pid='speaker:'+speaker;people[pid]={'id':pid,'kind':'metadata','speaker_id':speaker}
                arguments.append({'event_id':eid,'role':'speaker','participant_id':pid})
                if attributes['speech_act']=='request':arguments.append({'event_id':eid,'role':'requester','participant_id':pid})
            if attributes['speech_act']=='request':
                actor=opt.get('performer')
                if actor:
                    pid='speaker:'+actor;people[pid]={'id':pid,'kind':'metadata','speaker_id':actor}
                else:
                    pid='unknown:'+message['id']+':addressee';people[pid]={'id':pid,'kind':'unknown'}
                arguments += [{'event_id':eid,'role':'performer','participant_id':pid},{'event_id':eid,'role':'affected_party','participant_id':pid}]
            # Keep entire supporting clause as an argument span, separately from trigger.
            full=opt.get('argument')
            if full:
                start=message['text'].index(full);aid='arg'+str(i);spans.append({'id':aid,'message_id':message['id'],'start':start,'end':start+len(full),'quote':full,'label':opt.get('argument_label','condition')});events[-1]['argument_refs']=[aid]
        rels=[]
        for i,(a,b,typ) in enumerate(links):
            evidence=list(dict.fromkeys([events[a]['anchor_id'],events[b]['anchor_id'],*events[a]['argument_refs'],*events[b]['argument_refs']]))
            rels.append({'id':'r'+str(i),'type':typ,'source_id':'e'+str(a),'target_id':'e'+str(b),'scope_id':events[a]['transaction_id'],'evidence_refs':evidence})
        for m in ms:
            if m['speaker_id']:people.setdefault('speaker:'+m['speaker_id'],{'id':'speaker:'+m['speaker_id'],'kind':'metadata','speaker_id':m['speaker_id']})
        cases=[]
        for scope in dict.fromkeys(e['transaction_id'] for e in events):cases.append({'id':scope,'event_refs':[e['id'] for e in events if e['transaction_id']==scope],'participant_refs':list(people)})
